import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Cursor from "./Cursor";
import {
  FaInstagram,
  FaYoutube,
  FaFacebookF,
  FaTwitter,
  FaTiktok,
} from "react-icons/fa";

export default function LandingPage() {
  const socials = [
    { icon: FaInstagram, link: "https://instagram.com" },
    { icon: FaYoutube, link: "https://youtube.com" },
    { icon: FaFacebookF, link: "https://facebook.com" },
    { icon: FaTwitter, link: "https://x.com" },
    { icon: FaTiktok, link: "https://tiktok.com" },
  ];

  const eventDate = new Date("2026-06-30T18:00:00").getTime();

  const [timeLeft, setTimeLeft] = useState({
    days: "00",
    hours: "00",
    minutes: "00",
    seconds: "00",
  });

  function getTimeRemaining() {
    const now = new Date().getTime();
    const distance = eventDate - now;

    if (distance <= 0) {
      return {
        days: "00",
        hours: "00",
        minutes: "00",
        seconds: "00",
      };
    }

    return {
      days: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(
        2,
        "0"
      ),
      hours: String(Math.floor((distance / (1000 * 60 * 60)) % 24)).padStart(
        2,
        "0"
      ),
      minutes: String(Math.floor((distance / (1000 * 60)) % 60)).padStart(
        2,
        "0"
      ),
      seconds: String(Math.floor((distance / 1000) % 60)).padStart(2, "0"),
    };
  }

  useEffect(() => {
    const updateTime = () => {
      setTimeLeft(getTimeRemaining());
    };

    updateTime();
    const timer = setInterval(updateTime, 1000);

    return () => clearInterval(timer);
  }, []);

  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = (id) => {
    const section = document.getElementById(id);

    if (section) {
      section.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }

    setMenuOpen(false);
  };

  // Close menu on window resize
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 768) {
        setMenuOpen(false);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <>
      <Cursor />
      <div className="bg-black text-white font-[Inter] overflow-x-hidden">
        {/* NAVBAR */}
        <nav className="fixed w-full z-50 bg-black/95 backdrop-blur-sm border-b border-neutral-900">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
            {/* LOGO */}
            <div className="flex items-center z-50">
              <img
                src="/gfc-logo.png"
                alt="GFC Logo"
                className="h-10 sm:h-12 md:h-14 lg:h-16 object-contain cursor-pointer"
                onClick={() => handleScroll("home")}
              />
            </div>

            {/* DESKTOP MENU */}
            <ul className="hidden md:flex gap-6 lg:gap-8 text-[10px] lg:text-xs uppercase tracking-wider">
              {navItems.map((item) => (
                <li
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="hover:text-red-500 transition cursor-pointer"
                >
                  {item.name}
                </li>
              ))}
            </ul>

            {/* DESKTOP TICKET BUTTON */}
            <button className="hidden md:block bg-red-600 px-4 lg:px-6 py-2 lg:py-2.5 text-[10px] lg:text-xs font-semibold hover:bg-red-700 transition">
              GET TICKETS
            </button>

            {/* MOBILE HAMBURGER */}
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              className="md:hidden z-50 w-10 h-10 flex flex-col items-center justify-center gap-1.5"
              aria-label="Toggle menu"
            >
              <span
                className={`w-6 h-0.5 bg-white transition-all duration-300 ${
                  menuOpen ? "rotate-45 translate-y-2" : ""
                }`}
              />
              <span
                className={`w-6 h-0.5 bg-white transition-all duration-300 ${
                  menuOpen ? "opacity-0" : ""
                }`}
              />
              <span
                className={`w-6 h-0.5 bg-white transition-all duration-300 ${
                  menuOpen ? "-rotate-45 -translate-y-2" : ""
                }`}
              />
            </button>
          </div>

          {/* MOBILE MENU */}
          <AnimatePresence>
            {menuOpen && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.3 }}
                className="md:hidden bg-black border-t border-neutral-800 overflow-hidden"
              >
                <div className="flex flex-col items-center py-6 gap-4">
                  {navItems.map((item) => (
                    <motion.div
                      key={item.id}
                      initial={{ opacity: 0, y: -10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.2 }}
                      onClick={() => handleScroll(item.id)}
                      className="text-sm uppercase tracking-wide hover:text-red-500 transition cursor-pointer"
                    >
                      {item.name}
                    </motion.div>
                  ))}
                  <button className="bg-red-600 px-6 py-2.5 text-xs font-semibold mt-2 hover:bg-red-700 transition w-[200px]">
                    GET TICKETS
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </nav>

        {/* HERO SECTION */}
        <section
          id="home"
          className="relative pt-16 min-h-screen flex items-center bg-black overflow-hidden"
        >
          {/* BACKGROUND IMAGE */}
          <div className="absolute inset-0 flex justify-end pointer-events-none">
            <img
              src="/fighter.png"
              alt="fighter"
              className="w-[150%] sm:w-[90%] md:w-[70%] lg:w-[60%] xl:w-[55%] max-w-[1000px] h-full object-cover object-left opacity-70 md:opacity-80"
            />
          </div>

          {/* GRADIENT OVERLAY */}
          <div className="absolute inset-0 bg-gradient-to-r from-black via-black/95 to-transparent" />

          {/* CONTENT */}
          <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full py-12 sm:py-16 md:py-20">
            <div className="w-full max-w-full sm:max-w-[600px] lg:max-w-[700px]">
              <p className="text-red-500 text-[10px] sm:text-xs uppercase tracking-[2px] mb-3 sm:mb-4">
                GFC GLOBAL 1: ORIGIN
              </p>

              <h1 className="font-[Anton] italic uppercase tracking-[1px] leading-none text-[40px] sm:text-[56px] md:text-[80px] lg:text-[100px] xl:text-[120px]">
                <span className="block">FIGHTS.</span>
                <span className="block">STORIES.</span>
                <span className="block text-red-500">LEGENDS.</span>
              </h1>

              <p className="mt-4 sm:mt-6 text-gray-300 text-sm sm:text-base md:text-lg">
                India's Next Combat Sports Movement
              </p>

              <div className="flex flex-col sm:flex-row gap-3 sm:gap-4 mt-6 sm:mt-8">
                <button className="bg-red-600 px-6 sm:px-8 py-3 sm:py-3.5 text-xs sm:text-sm font-semibold hover:bg-red-700 transition w-full sm:w-auto">
                  GET TICKETS
                </button>

                <button className="border border-white px-6 sm:px-8 py-3 sm:py-3.5 text-xs sm:text-sm hover:bg-white hover:text-black transition w-full sm:w-auto flex items-center justify-center gap-2">
                  <span>▶</span> WATCH TRAILER
                </button>
              </div>
            </div>
          </div>
        </section>

        {/* FEATURES SECTION */}
        <section id="about" className="border-t border-neutral-900 py-8 sm:py-12">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4 sm:gap-6 lg:gap-8">
              {features.map((item, i) => (
                <div
                  key={i}
                  className="text-center border-r border-neutral-800 last:border-none pr-2 sm:pr-4"
                >
                  <i
                    className={`fa ${item.icon} text-red-500 text-xl sm:text-2xl lg:text-3xl mb-2 sm:mb-3`}
                  />

                  <h3 className="text-[10px] sm:text-xs font-bold uppercase mb-1">
                    {item.title}
                  </h3>

                  <p className="text-[9px] sm:text-xs text-gray-500 leading-tight">
                    {item.desc}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* ABOUT + FIGHTERS SECTION */}
        <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 sm:py-16 lg:py-20">
          <div className="grid lg:grid-cols-2 gap-8 lg:gap-12 items-start">
            {/* LEFT TEXT */}
            <div className="max-w-full lg:max-w-md">
              <p className="text-red-600 text-[10px] sm:text-xs tracking-widest uppercase mb-3">
                ABOUT GFC
              </p>

              <h2 className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-extrabold leading-tight uppercase">
                WE ARE BUILDING <br />
                MORE THAN EVENTS.
                <br />
                <span className="text-red-600">
                  WE ARE BUILDING A MOVEMENT.
                </span>
              </h2>

              <p className="text-gray-400 text-sm sm:text-base mt-4 sm:mt-6 leading-relaxed">
                GFC is a combat sports platform focused on fighters, content and
                culture. Our mission is to give fighters the stage they deserve
                and fans the experience they will never forget.
              </p>

